  const password = watch("password")

  // Set initial tab based on URL parameter
  useEffect(() => {
    const role = searchParams.get("role")
    if (role === "coach") {
      setActiveTab("coach")
    }
  }, [searchParams])

  const onSubmit = async (data: SignUpForm) => {
    setIsLoading(true)
    setError(null)

    try {
      // Validate inputs on client side
      const emailValidation = validateEmail(data.email)
      if (!emailValidation) {
        setError("Please enter a valid email address")
        return
      }

      const passwordValidation = validatePassword(data.password)
      if (!passwordValidation.isValid) {
        setError(`Password requirements not met: ${passwordValidation.errors[0]}`)
        return
      }

      // Sanitize inputs
      const sanitizedEmail = sanitizeAuthInput(data.email)
      const sanitizedName = sanitizeAuthInput(data.name)

      // Sign up the user with metadata for the trigger
      const { data: authData, error: signUpError } = await supabase.auth.signUp({
        email: sanitizedEmail,
        password: data.password,
        options: {
          data: {
            role: activeTab,
            name: sanitizedName,
            phone: data.phone ? sanitizeAuthInput(data.phone) : null,
          }
        }
      })

      if (signUpError) {
        setError(signUpError.message)
        return
      }

      if (!authData.user) {
        setError("Failed to create account")
        return
      }

