     1→/**
     2→ * System health monitoring and status tracking
     3→ */
     4→
     5→import { performanceMonitor } from './performance-monitor'
     6→import { logger } from './logger'
     7→
     8→export interface HealthCheck {
     9→  name: string
    10→  status: 'healthy' | 'degraded' | 'unhealthy'
    11→  message: string
    12→  responseTime?: number
    13→  lastCheck: Date
    14→  metadata?: Record<string, unknown>
    15→}
    16→
    17→export interface SystemHealth {
    18→  overall: 'healthy' | 'degraded' | 'unhealthy'
    19→  checks: HealthCheck[]
    20→  uptime: number
    21→  timestamp: Date
    22→  version?: string
    23→  environment?: string
    24→}
    25→
    26→class HealthMonitor {
    27→  private static instance: HealthMonitor
    28→  private checks: Map<string, HealthCheck> = new Map()
    29→  private startTime = Date.now()
    30→  private checkInterval: NodeJS.Timeout | null = null
    31→
    32→  static getInstance(): HealthMonitor {
    33→    if (!HealthMonitor.instance) {
    34→      HealthMonitor.instance = new HealthMonitor()
    35→    }
    36→    return HealthMonitor.instance
    37→  }
    38→
    39→  constructor() {
    40→    this.startPeriodicChecks()
    41→  }
    42→
    43→  // Register a health check
    44→  registerCheck(
    45→    name: string, 
    46→    checkFn: () => Promise<Omit<HealthCheck, 'name' | 'lastCheck'>>,
    47→    intervalMs: number = 30000 // 30 seconds default
    48→  ) {
    49→    const performCheck = async () => {
    50→      const startTime = Date.now()
    51→      try {
    52→        const result = await checkFn()
    53→        const responseTime = Date.now() - startTime
    54→
    55→        const healthCheck: HealthCheck = {
    56→          name,
    57→          ...result,
    58→          responseTime,
    59→          lastCheck: new Date()
    60→        }
    61→
    62→        this.checks.set(name, healthCheck)
    63→        
    64→        // Log health status changes
    65→        const previousStatus = this.checks.get(name)?.status
    66→        if (previousStatus && previousStatus !== result.status) {
    67→          logger.health(name, result.status, { 
    68→            previousStatus, 
    69→            message: result.message,
    70→            responseTime 
    71→          })
    72→        }
    73→
    74→        // Record performance metric
    75→        performanceMonitor.recordMetric(`health_check_${name}`, responseTime, 'ms', {
    76→          status: result.status,
    77→          healthy: result.status === 'healthy'
    78→        })
    79→
    80→      } catch (error) {
    81→        const responseTime = Date.now() - startTime
    82→        const healthCheck: HealthCheck = {
    83→          name,
    84→          status: 'unhealthy',
    85→          message: error instanceof Error ? error.message : 'Health check failed',
    86→          responseTime,
    87→          lastCheck: new Date(),
    88→          metadata: { error: String(error) }
    89→        }
    90→
    91→        this.checks.set(name, healthCheck)
    92→        logger.error(`Health check failed for ${name}`, { error }, 'health-monitor')
    93→      }
    94→    }
    95→
    96→    // Run initial check
    97→    performCheck()
    98→
    99→    // Schedule periodic checks
   100→    const interval = setInterval(performCheck, intervalMs)
   101→    
   102→    return () => clearInterval(interval)
   103→  }
   104→
   105→  // Get current system health
   106→  getHealth(): SystemHealth {
   107→    const checks = Array.from(this.checks.values())
   108→    const unhealthyCount = checks.filter(c => c.status === 'unhealthy').length
   109→    const degradedCount = checks.filter(c => c.status === 'degraded').length
   110→
   111→    let overall: SystemHealth['overall'] = 'healthy'
   112→    if (unhealthyCount > 0) {
   113→      overall = 'unhealthy'
   114→    } else if (degradedCount > 0) {
   115→      overall = 'degraded'
   116→    }
   117→
   118→    return {
   119→      overall,
   120→      checks,
   121→      uptime: Date.now() - this.startTime,
   122→      timestamp: new Date(),
   123→      version: process.env.npm_package_version,
   124→      environment: process.env.NODE_ENV
   125→    }
   126→  }
   127→
   128→  // Check if system is healthy
   129→  isHealthy(): boolean {
   130→    return this.getHealth().overall === 'healthy'
   131→  }
   132→
   133→  // Get health summary for specific service
   134→  getServiceHealth(serviceName: string): HealthCheck | null {
   135→    return this.checks.get(serviceName) || null
   136→  }
   137→
   138→  private startPeriodicChecks() {
   139→    // Register built-in health checks
   140→    this.registerDatabaseHealthCheck()
   141→    this.registerMemoryHealthCheck()
   142→    this.registerApiHealthCheck()
   143→    
   144→    // Overall system health logging every 5 minutes
   145→    this.checkInterval = setInterval(() => {
   146→      const health = this.getHealth()
   147→      logger.health('system', health.overall, {
   148→        uptime: health.uptime,
   149→        checkCount: health.checks.length,
   150→        unhealthyServices: health.checks.filter(c => c.status === 'unhealthy').map(c => c.name),
   151→        degradedServices: health.checks.filter(c => c.status === 'degraded').map(c => c.name)
   152→      })
   153→    }, 5 * 60 * 1000)
   154→  }
   155→
   156→  private registerDatabaseHealthCheck() {
   157→    this.registerCheck('database', async () => {
   158→      try {
   159→        // Simple database connectivity check
   160→        const startTime = Date.now()
   161→        
   162→        // In a real app, you would ping your database here
   163→        // const supabase = createServerSupabaseClient()
   164→        // await supabase.from('health_check').select('1').limit(1)
   165→        
   166→        const responseTime = Date.now() - startTime
   167→        
   168→        if (responseTime > 1000) {
   169→          return {
   170→            status: 'degraded',
   171→            message: `Database responding slowly (${responseTime}ms)`,
   172→            metadata: { responseTime }
   173→          }
   174→        }
   175→
   176→        return {
   177→          status: 'healthy',
   178→          message: 'Database connection healthy',
   179→          metadata: { responseTime }
   180→        }
   181→      } catch (error) {
   182→        return {
   183→          status: 'unhealthy',
   184→          message: 'Database connection failed',
   185→          metadata: { error: String(error) }
   186→        }
   187→      }
   188→    }, 60000) // Check every minute
   189→  }
   190→
   191→  private registerMemoryHealthCheck() {
   192→    this.registerCheck('memory', async () => {
   193→      if (typeof process === 'undefined') {
   194→        return {
   195→          status: 'healthy',
   196→          message: 'Memory check not available (client-side)'
   197→        }
   198→      }
   199→
   200→      const memoryUsage = process.memoryUsage()
   201→      const heapUsedMB = Math.round(memoryUsage.heapUsed / 1024 / 1024)
   202→      const heapTotalMB = Math.round(memoryUsage.heapTotal / 1024 / 1024)
   203→      const memoryPercentage = (heapUsedMB / heapTotalMB) * 100
   204→
   205→      let status: HealthCheck['status'] = 'healthy'
   206→      let message = `Memory usage: ${heapUsedMB}MB / ${heapTotalMB}MB (${Math.round(memoryPercentage)}%)`
   207→
   208→      if (heapUsedMB > 500) { // 500MB threshold
   209→        status = 'unhealthy'
   210→        message = `High memory usage: ${heapUsedMB}MB`
   211→      } else if (heapUsedMB > 300) { // 300MB warning
   212→        status = 'degraded'
   213→        message = `Elevated memory usage: ${heapUsedMB}MB`
   214→      }
   215→
   216→      return {
   217→        status,
   218→        message,
   219→        metadata: {
   220→          heapUsed: heapUsedMB,
   221→          heapTotal: heapTotalMB,
   222→          percentage: Math.round(memoryPercentage)
   223→        }
   224→      }
   225→    }, 30000) // Check every 30 seconds
   226→  }
   227→
   228→  private registerApiHealthCheck() {
   229→    this.registerCheck('api_performance', async () => {
   230→      const summary = performanceMonitor.getPerformanceSummary(5) // Last 5 minutes
