  message: string
  responseTime?: number
  lastCheck: Date
  metadata?: Record<string, unknown>
}

export interface SystemHealth {
  overall: 'healthy' | 'degraded' | 'unhealthy'
  checks: HealthCheck[]
  uptime: number
  timestamp: Date
  version?: string
  environment?: string
}

