    if (dates.length === 0) {
      setError("Please add at least one date")
      return
    }

    if (timeslots.length === 0) {
      setError("Please add at least one timeslot")
      return
    }

    setIsLoading(true)
    setError(null)

    try {
      const { data: { user } } = await supabase.auth.getUser()

      if (!user) {
        setError("You must be logged in to post a listing")
        return
      }

      const { data: listing, error: insertError } = await supabase
        .from('listings')
        .insert({
          org_id: user.id,
          title: data.title,
          description: data.description,
          location: data.location,
          dates,
          timeslots,
          pay_min: data.pay_min,
          pay_max: data.pay_max,
          required_badges: requiredBadges,
          urgency: data.urgency,
          status: 'active'
        })
        .select()
        .single()

      if (insertError) {
        setError(insertError.message)
        return
      }

      router.push(`/org/listings/${listing.id}`)
