              <div className="relative">
                <DollarSign className="absolute left-3 top-3 w-4 h-4 text-muted-foreground" />
                <Input
                  id="pay_min"
                  type="number"
                  className="pl-10"
                  placeholder="50"
                  {...register("pay_min", {
