      <h1 className="text-3xl font-bold mb-8">Post a Coaching Need</h1>

      <form onSubmit={handleSubmit(onSubmit)} className="space-y-8">
        {error && (
          <div className="p-4 rounded-lg bg-destructive/10 text-destructive flex items-start gap-3">
            <AlertCircle className="w-5 h-5 shrink-0" />
            <span>{error}</span>
          </div>
        )}

        {/* Basic Information */}
        <GlassCard>
          <h2 className="text-xl font-semibold mb-4">Basic Information</h2>

          <div className="space-y-4">
            <div className="space-y-2">
              <Label htmlFor="title">Title *</Label>
              <Input
                id="title"
                placeholder="e.g., Youth Basketball Coach for U14 Team"
                {...register("title", {
                  required: "Title is required",
                  minLength: {
                    value: 10,
                    message: "Title must be at least 10 characters"
                  }
                })}
              />
              {errors.title && (
                <p className="text-sm text-destructive">{errors.title.message}</p>
              )}
            </div>

            <div className="space-y-2">
              <Label htmlFor="description">Description</Label>
              <Textarea
                id="description"
                rows={4}
                placeholder="Describe the coaching role, expectations, skill level of players, etc."
                {...register("description")}
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="location">Location *</Label>
              <div className="relative">
                <MapPin className="absolute left-3 top-3 w-4 h-4 text-muted-foreground" />
                <Input
                  id="location"
                  className="pl-10"
                  placeholder="e.g., Bondi Beach Basketball Courts, Sydney"
                  {...register("location", {
                    required: "Location is required"
                  })}
                />
              </div>
              {errors.location && (
                <p className="text-sm text-destructive">{errors.location.message}</p>
              )}
            </div>

            <div className="space-y-2">
              <Label htmlFor="urgency">Urgency</Label>
              <Select 
                defaultValue="flexible"
                onValueChange={(value) => register("urgency").onChange({ target: { value } })}
              >
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="urgent">Urgent (Need within 48 hours)</SelectItem>
                  <SelectItem value="soon">Soon (Within a week)</SelectItem>
                  <SelectItem value="flexible">Flexible</SelectItem>
                </SelectContent>
              </Select>
            </div>
          </div>
        </GlassCard>

        {/* Schedule */}
        <GlassCard>
          <h2 className="text-xl font-semibold mb-4">Schedule</h2>

          <div className="space-y-4">
            <div className="space-y-2">
              <Label>Dates *</Label>
              <div className="flex gap-2">
                <Input
                  type="date"
                  value={currentDate}
                  onChange={(e) => setCurrentDate(e.target.value)}
                  min={new Date().toISOString().split('T')[0]}
                />
                <Button type="button" onClick={addDate} disabled={!currentDate}>
                  <Plus className="w-4 h-4" />
                </Button>
              </div>
              <div className="flex flex-wrap gap-2 mt-2">
                {dates.map((date) => (
                  <Badge key={date} variant="secondary" className="flex items-center gap-1">
                    <Calendar className="w-3 h-3" />
                    {new Date(date).toLocaleDateString()}
                    <button
                      type="button"
                      onClick={() => removeDate(date)}
                      className="ml-1 hover:text-destructive"
                    >
                      <X className="w-3 h-3" />
                    </button>
                  </Badge>
                ))}
              </div>
            </div>

            <div className="space-y-2">
              <Label>Time Slots *</Label>
              <div className="flex gap-2">
                <Input
                  type="time"
                  value={currentTimeslot}
                  onChange={(e) => setCurrentTimeslot(e.target.value)}
                />
                <Button type="button" onClick={addTimeslot} disabled={!currentTimeslot}>
                  <Plus className="w-4 h-4" />
                </Button>
              </div>
              <div className="flex flex-wrap gap-2 mt-2">
                {timeslots.map((slot) => (
                  <Badge key={slot} variant="secondary" className="flex items-center gap-1">
                    <Clock className="w-3 h-3" />
                    {slot}
                    <button
                      type="button"
                      onClick={() => removeTimeslot(slot)}
                      className="ml-1 hover:text-destructive"
                    >
                      <X className="w-3 h-3" />
                    </button>
                  </Badge>
                ))}
              </div>
            </div>
          </div>
        </GlassCard>

        {/* Compensation */}
        <GlassCard>
          <h2 className="text-xl font-semibold mb-4">Compensation (Optional)</h2>
          <p className="text-sm text-muted-foreground mb-4">
            Providing a pay range helps attract more qualified coaches
          </p>

          <div className="grid md:grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="pay_min">Minimum Rate ($/hour)</Label>
              <div className="relative">
                <DollarSign className="absolute left-3 top-3 w-4 h-4 text-muted-foreground" />
                <Input
                  id="pay_min"
                  type="number"
                  className="pl-10"
                  placeholder="50"
                  {...register("pay_min", {
                    min: { value: 0, message: "Rate must be positive" }
                  })}
                />
              </div>
            </div>

            <div className="space-y-2">
              <Label htmlFor="pay_max">Maximum Rate ($/hour)</Label>
              <div className="relative">
                <DollarSign className="absolute left-3 top-3 w-4 h-4 text-muted-foreground" />
                <Input
                  id="pay_max"
                  type="number"
                  className="pl-10"
                  placeholder="80"
                  {...register("pay_max", {
                    min: { value: 0, message: "Rate must be positive" }
                  })}
                />
              </div>
            </div>
          </div>
        </GlassCard>

        {/* Required Certifications */}
        <GlassCard>
          <h2 className="text-xl font-semibold mb-4">Required Certifications</h2>
          <p className="text-sm text-muted-foreground mb-4">
            Select any certifications that are mandatory for this role
          </p>

          <div className="space-y-3">
            {availableBadges.map((badge) => (
              <label
                key={badge.value}
                className="flex items-center gap-3 cursor-pointer"
              >
                <input
                  type="checkbox"
                  checked={requiredBadges.includes(badge.value)}
                  onChange={() => toggleBadge(badge.value)}
                  className="rounded border-border"
                />
                <div className="flex items-center gap-2">
                  <Shield className="w-4 h-4 text-muted-foreground" />
                  <span>{badge.label}</span>
                </div>
              </label>
            ))}
          </div>
        </GlassCard>

        {/* Actions */}
        <div className="flex gap-4">
          <Button
            type="submit"
            size="lg"
            disabled={isLoading}
            className="flex-1"
          >
            {isLoading ? "Posting..." : "Post Listing"}
          </Button>
          <Button
            type="button"
            size="lg"
            variant="outline"
            onClick={() => router.back()}
          >
            Cancel
          </Button>
        </div>
      </form>
    </div>
  )
}

